    .{ .first = 0x205f, .last = 0x205f },
    .{ .first = 0x3000, .last = 0x3000 },
};

pub fn isWhiteSpace(codepoint: u21) bool {
    var low: usize = 0;
    var high: usize = whitespace_ranges.len;
    while (low < high) {
        const mid = low + (high - low) / 2;
        const range = whitespace_ranges[mid];
        if (codepoint < range.first) high = mid else if (codepoint > range.last) low = mid + 1 else return true;
    }
    return false;
}

