pub fn isMath(codepoint: u21) bool {
    var low: usize = 0;
    var high: usize = math_ranges.len;
    while (low < high) {
        const mid = low + (high - low) / 2;
        const range = math_ranges[mid];
        if (codepoint < range.first) high = mid else if (codepoint > range.last) low = mid + 1 else return true;
    }
    return false;
}

